checks.script:
const a = new BankAccount("Ama", 100);
a.deposit(50);
if (a.getBalance() !== 150) throw new Error("balance after deposit should be 150, got " + a.getBalance());
a.withdraw(30);
if (a.getBalance() !== 120) throw new Error("balance after withdrawal should be 120");
if (a.getOwner() !== "Ama") throw new Error("getOwner should return Ama");
if (a.balance !== undefined) throw new Error("the balance must not be a public property");

const a = new BankAccount("Kofi", 20);
let threw = false;
try { a.withdraw(50); } catch (e) { threw = /insufficient/i.test(e.message); }
if (!threw) throw new Error("withdraw(50) on a balance of 20 must throw Insufficient funds");
if (a.getBalance() !== 20) throw new Error("a failed withdrawal must not change the balance");
let bad = false;
try { a.deposit(-5); } catch (e) { bad = true; }
if (!bad) throw new Error("deposit(-5) must throw");
let neg = false;
try { new BankAccount("x", -1); } catch (e) { neg = true; }
if (!neg) throw new Error("a negative opening balance must throw");
